using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.FNZ.TiposMovimiento;using GraphApi.Services.FNZ.TiposMovimiento;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.FNZ.TiposMovimiento{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de TiposMovimientos: creación, actualización y eliminación.")]    public class TiposMovimientoMutation    {        [Authorize]        [GraphQLName("createTiposMovimiento")]        [GraphQLDescription("Crea un nuevo TiposMovimiento usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTiposMovimiento> CreateTiposMovimientoAsync(            [GraphQLDescription("Datos necesarios para crear el TiposMovimiento.")]            clCreateTiposMovimiento objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposMovimiento.")]            ITiposMovimientoService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTiposMovimiento(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTiposMovimiento")]        [GraphQLDescription("Actualiza los campos especificados de un TiposMovimiento existente.")]        public async Task<clReadTiposMovimiento?> UpdateTiposMovimientoAsync(            [GraphQLDescription("Datos del TiposMovimiento a actualizar.")]            clUpdateTiposMovimiento objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposMovimiento.")]            ITiposMovimientoService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTiposMovimiento(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTiposMovimiento")]        [GraphQLDescription("Elimina un TiposMovimiento por su ID.")]        public async Task<bool> delTiposMovimientoAsync(            [GraphQLDescription("ID del TiposMovimiento a eliminar.")]            int nTiposMovimientoID,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposMovimiento.")]            ITiposMovimientoService objService        )        {            return await objService.DeleteTiposMovimiento(nTiposMovimientoID);        }    }}